  if(action==='collapse'){collapsed=!collapsed;renderSidebar();return;}
  if(action==='members'){if(active.dm&&matchMedia('(max-width:760px)').matches){membersVisible=true;document.body.classList.toggle('dm-profile-open');}else membersVisible=!membersVisible;renderChat();return;}
  if(action==='full-user-profile'){document.querySelector('#user-mini-profile')?.hidePopover();window.BiscordFullProfile.open({person:person(id),api:backend,icon,getNote:()=>db.profileNotes?.[id]||'',setNote:async value=>{db.profileNotes??={};db.profileNotes[id]=value;save();await backend.flush();},onMessage:()=>route('/channels/@me/'+encodeURIComponent(id)),onMore:()=>showModal('Opções de '+person(id).name,`<div class="modal-list"><button data-action="block" data-id="${esc(id)}">Bloquear usuário</button></div>`)});return;}
  if(action==='quick-switch'){quickSwitch();return;}
  if(action==='new-server'){showModal('Crie seu servidor',`<p class="modal-copy">Um lugar para você e seus amigos conversarem.</p><button class="button secondary" type="button" data-action="join-server">Já tem um convite? Entrar em um servidor</button><form id="new-server-form"><label class="modal-field"><span>Nome do servidor</span><input name="name" value="Servidor de ${esc(profile.displayName)}" maxlength="48" minlength="2" required></label><div class="modal-error" id="server-error"></div><div class="modal-actions"><button class="button link" type="button" data-action="close-modal">Cancelar</button><button class="button" type="submit">Criar servidor</button></div></form>`);return;}
  if(action==='new-channel'){showModal('Criar canal',`<form id="new-channel-form"><label class="modal-field"><span>Tipo de canal</span><select name="type"><option value="text">Texto — mensagens e imagens</option><option value="voice">Voz — prévia da sala</option></select></label><label class="modal-field"><span>Nome do canal</span><input name="name" placeholder="novo-canal" maxlength="40" required></label><div class="modal-actions"><button class="button link" type="button" data-action="close-modal">Cancelar</button><button class="button" type="submit">Criar canal</button></div></form>`);return;}
  if(action==='server-boosts'){route('/channels/'+currentServer().id+'/boosts');return;}if(action==='server-settings'){openServerSettings(target.dataset.page||'profile');return;}if(action==='server-menu'){showServerActions();return;}
  if(action==='invite'){const link=location.origin+'/channels/'+active.server+'/'+currentServer().channels[0].id;showModal('Convide a sua turma',`<p class="modal-copy">Este link abre um espaço de trabalho privado, sincronizado apenas com a sua conta.</p><label class="modal-field"><span>Link local</span><input value="${esc(link)}" readonly id="invite-link"></label><div class="modal-actions"><button class="button" data-action="copy-invite">Copiar link</button></div>`);return;}
  if(action==='copy-invite'){try{await navigator.clipboard.writeText(document.querySelector('#invite-link').value);toast('Link local copiado.');}catch{document.querySelector('#invite-link').select();toast('Selecione e copie o link.');}return;}
  if(['accept-friend','cancel-friend','unblock','block'].includes(action)){try{await socialAction(id,{'accept-friend':'accept','cancel-friend':'cancel',unblock:'unblock',block:'block'}[action]);if(action==='block'){modal.close();route('/channels/@me');}}catch(e){toast(e.message);}return;}
  if(action==='friend-menu'){const p=person(id);showModal(p.name,`<div class="modal-list"><button data-action="dm" data-id="${esc(id)}">${icon('chat')}Enviar mensagem</button><button data-action="profile" data-id="${esc(id)}">${icon('friends')}Ver perfil</button><button data-action="block" data-id="${esc(id)}" style="color:#f18189">${icon('close')}Bloquear usuário</button></div>`);return;}
  if(action==='profile'){if(id==='self')showSelfProfile();else showProfile(id,target);return;}
  if(action==='emoji'){const picker=document.querySelector('#emoji-picker');picker.hidden=!picker.hidden;return;}
  if(action==='insert-emoji'){const input=document.querySelector('#message-input');input.value+=target.dataset.emoji;document.querySelector('#emoji-picker').hidden=true;input.focus();return;}
  if(action==='attach'){document.querySelector('#attachment-input')?.click();return;}
  if(action==='reaction'||action==='react'){if(active.dm){try{await backend.request('/dm/'+encodeURIComponent(id),{method:'PATCH',body:{action:'reaction',emoji:target.dataset.emoji||'👍'}});}catch(e){toast(e.message);}return;}const m=messageById(id);if(!m)return;const emoji=target.dataset.emoji||'👍';if(!m.reactions)m.reactions=[];let r=m.reactions.find(r=>r.emoji===emoji);if(!r){r={emoji,count:1,mine:true};m.reactions.push(r);}else{r.count+=r.mine?-1:1;r.mine=!r.mine;m.reactions=m.reactions.filter(r=>r.count>0);}save();renderChat();return;}
  if(action==='reply'){const m=messageById(id);if(m){replyTo=m;const label=document.querySelector('#reply-label');label.hidden=false;label.textContent='Respondendo a '+person(m.author).name;document.querySelector('#message-input').focus();}return;}
  if(action==='delete-message'){if(active.dm){try{await backend.request('/dm/'+encodeURIComponent(id),{method:'DELETE',body:{}});}catch(e){toast(e.message);}return;}db.messages[conversation()]=(db.messages[conversation()]||[]).filter(m=>m.id!==id||m.author!=='self');save();renderChat();return;}
  if(action==='message-menu'){showModal('Mensagem',`<div class="modal-list"><button data-action="reply-modal" data-id="${esc(id)}">${icon('chat')}Responder</button><button data-action="pin-message" data-id="${esc(id)}">${icon('pin')}Fixar nesta conversa local</button></div>`);return;}
  if(action==='reply-modal'){modal.close();replyTo=messageById(id);renderChat();document.querySelector('#message-input')?.focus();return;}
  if(action==='pin-message'){if(active.dm){try{await backend.request('/dm/'+encodeURIComponent(id),{method:'PATCH',body:{action:'pin',pinned:true}});modal.close();}catch(e){toast(e.message);}return;}const m=messageById(id);if(m)m.pinned=true;save();modal.close();toast('Mensagem fixada nesta conversa.');return;}
  if(action==='pins'){let pinned=(db.messages[conversation()]||[]).filter(m=>m.pinned);try{const remote=await backend.findMessages(conversation(),{pinned:true});pinned=[...new Map([...pinned,...remote.map(r=>r.m)].map(m=>[m.id,m])).values()];}catch(e){toast(e.message);return;}showModal('Mensagens fixadas',pinned.length?pinned.map(m=>`<p class="modal-copy"><strong>${esc(person(m.author).name)}</strong><br>${esc(m.text)}</p>`).join(''):'<p class="modal-copy">Nenhuma mensagem fixada nesta conversa.</p>');return;}
  if(action==='retry-dm'){const key=conversation(),m=db.messages[key]?.find(m=>m.id===id);if(!m)return;const endpoint=active.dm?'/dm/'+encodeURIComponent(active.dm):currentServer()?.shared?'/servers/'+encodeURIComponent(active.server)+'/channels/'+encodeURIComponent(active.channel)+'/messages':null;if(!endpoint)return;m.delivery='pending';refreshMessages({key,ids:[id]});try{const result=await backend.request(endpoint,{method:'POST',body:{text:m.text,image:m.image,clientId:m.id}});Object.assign(m,result.message,{delivery:undefined});}catch(e){m.delivery='failed';m.error=e.message;}refreshMessages({key,ids:[id]});return;}
  if(action==='call'){voiceDM=active.dm;renderVoice();return;}
  if(action==='disconnect'){window.BiscordSounds?.play('disconnect');voiceConnection=null;voiceDM=null;renderSidebar();if(currentChannel()?.type==='voice')route('/channels/'+active.server+'/'+currentServer().channels.find(c=>c.type==='text').id);else if(active.server||active.dm)renderChat();else renderFriends();return;}
