 document.addEventListener('submit',async event=>{
  const form=event.target;event.preventDefault();
  if(form.id==='composer-form'){sendMessage();return;}
  const data=new FormData(form);
  if(form.id==='add-friend-form'){const name=String(data.get('username')||'').trim(),feedback=document.querySelector('#add-feedback');if(!/^[a-z0-9_.]{2,32}$/i.test(name)){feedback.textContent='Digite um nome de usuário válido.';feedback.style.color='#f18189';return;}if(name.toLowerCase()===profile.username.toLowerCase()||db.people.some(p=>p.username.toLowerCase()===name.toLowerCase())||db.pending.some(p=>p.username.toLowerCase()===name.toLowerCase())){feedback.textContent='Este nome já está na sua lista, ou é o seu próprio usuário.';return;}try{await backend.request('/friends/request',{method:'POST',body:{username:name}});await backend.refresh();refreshAccount(backend.session,backend.workspace);toast('Solicitação de amizade enviada.');}catch(e){feedback.textContent=e.message;feedback.style.color='#f18189';}return;}
  if(form.id==='new-server-form'){const name=String(data.get('name')||'').trim();if(name.length<2){document.querySelector('#server-error').textContent='Use um nome com pelo menos 2 caracteres.';return;}const id=crypto.randomUUID(),server=makeServer(id,name.slice(0,48),name.slice(0,1).toUpperCase(),colors[db.servers.length%colors.length]);const template=Number(sessionStorage.getItem('biscord-server-template')||0);sessionStorage.removeItem('biscord-server-template');const sets=[null,['geral','clips','jogos'],['geral','fotos','memes'],['geral','materiais','duvidas'],['geral','avisos','eventos'],['geral','avisos','encontros'],['geral','portfolio','feedback']];if(sets[template])server.channels=[...sets[template].map(name=>({id:name,name,type:'text'})),{id:'voz-geral',name:'Geral',type:'voice'}];db.servers.push(server);save();modal.close();route('/channels/'+id+'/geral');return;}
  if(form.id==='new-channel-form'){const server=currentServer();let name=String(data.get('name')||'').trim().slice(0,40);if(!name||!server)return;const type=data.get('type')==='voice'?'voice':'text';if(type==='text')name=name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'');if(!name){toast('Escolha um nome para o canal.');return;}const id=crypto.randomUUID();server.channels.push({id,name,type});save();modal.close();route('/channels/'+server.id+'/'+id);return;}
  if(form.id==='settings-form'){const name=String(data.get('displayName')||'').trim().slice(0,32);if(!name){toast('Digite um nome de exibição.');return;}profile.displayName=name;db.preferences.status=['online','idle','dnd','offline'].includes(data.get('status'))?data.get('status'):'online';db.preferences.theme=data.get('theme')==='light'?'light':'dark';try{sessionStorage.setItem('biscord-profile',JSON.stringify(profile));}catch{}save();modal.close();render();toast('Perfil atualizado.');return;}
  if(form.id==='message-search'){const query=String(data.get('query')||'').trim().toLowerCase();if(!query)return;let results=Object.entries(db.messages).filter(([key])=>db.preferences.searchAllDMs||key===conversation()).flatMap(([key,list])=>list.filter(m=>String(m.text).toLowerCase().includes(query)).map(m=>({key,m}))).slice(0,25);try{const remote=await backend.findMessages(conversation(),{query,all:db.preferences.searchAllDMs});results=[...new Map([...results,...remote].map(r=>[r.key+'\n'+r.m.id,r])).values()].sort((a,b)=>Date.parse(b.m.date)-Date.parse(a.m.date)).slice(0,25);}catch(e){toast(e.message);return;}showModal('Resultados da busca',results.length?results.map(({key,m})=>`<p class="modal-copy"><strong>${esc(person(m.author).name)}</strong> <small>${esc(key)}</small><br>${esc(m.text)}</p>`).join(''):'<p class="modal-copy">Nenhuma mensagem encontrada.</p>');}
 });
 document.addEventListener('input',event=>{const input=event.target;if(input.id==='friend-search'){let visible=0;document.querySelectorAll('[data-friend-search]').forEach(row=>{row.hidden=!row.dataset.friendSearch.includes(input.value.toLowerCase());if(!row.hidden)visible++;});document.querySelector('#friend-search-empty').hidden=visible>0||!input.value;}
  if(input.id==='quick-switch-input')document.querySelector('#quick-results').innerHTML=quickResults(input.value);
  if(input.id==='message-input'){input.style.height='auto';input.style.height=Math.min(input.scrollHeight,140)+'px';}
 });
 document.addEventListener('change',event=>{if(event.target.id!=='attachment-input')return;const file=event.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){toast('Escolha uma imagem PNG, JPG, WEBP ou GIF.');return;}if(file.size>600000){toast('Use uma imagem de até 600 KB nesta prévia local.');return;}const reader=new FileReader();reader.onload=()=>sendMessage(reader.result);reader.onerror=()=>toast('Não foi possível ler a imagem.');reader.readAsDataURL(file);});
 document.addEventListener('keydown',event=>{if(event.target.id==='message-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendMessage();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(modal.open)modal.close();quickSwitch();}if(event.key==='Escape'){closeSidebar();const picker=document.querySelector('#emoji-picker');if(picker)picker.hidden=true;replyTo=null;}});
 document.querySelector('#sidebar-backdrop').addEventListener('click',closeSidebar);
